#!/usr/bin/env bash\nset -euo pipefail\n\n# If an argument is provided, use it as uptime seconds; otherwise read from /proc/uptime\nif [[ $# -gt 0 ]]; then\n  uptime_seconds=$1\nelse\n  # Read first field from /proc/uptime and truncate to integer seconds\n  uptime_seconds=$(awk '{print int($1)}' /proc/uptime)\nfi\n\n# Compute days, hours, minutes\ndays=$(( uptime_seconds / 86400 ))\nhours=$(( (uptime_seconds % 86400) / 3600 ))\nminutes=$(( (uptime_seconds % 3600) / 60 ))\n\n# Define lyrical phrases\nphrases=(\n  "just woke up"\n  "still yawning"\n  "running like a hamster"\n  "still going strong"\n  "defying time"\n  "aging like fine wine"\n)\n\n# Choose phrase based on total minutes modulo number of phrases\ntotal_minutes=$(( uptime_seconds / 60 ))\nindex=$(( total_minutes % ${#phrases[@]} ))\nlyric=${phrases[$index]}\n\n# Output\necho "Uptime: ${days}d ${hours}h ${minutes}m – $lyric"
